import{c as a,Q as s,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const R=JSON.parse('{"title":"RegTensor","description":"","frontmatter":{},"headers":[{"level":1,"title":"RegTensor","slug":"regtensor"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"定义原型","slug":"定义原型"},{"level":2,"title":"函数说明","slug":"函数说明"},{"level":2,"title":"支持的型号","slug":"支持的型号"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/寄存器数据类型/RegTensor.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/寄存器数据类型/RegTensor.md"}'),i={name:"api/SIMD-API/基础API/Reg矢量计算/寄存器数据类型/RegTensor.md"};function l(p,e,r,d,c,o){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="regtensor" tabindex="-1">RegTensor <a class="header-anchor" href="#regtensor" aria-label="Permalink to &quot;RegTensor&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>Reg矢量计算基本单元，RegTensor位宽为VL（Vector Length），具体值可能因不同AI处理器型号而异。</p><h2 id="定义原型" tabindex="-1">定义原型 <a class="header-anchor" href="#定义原型" aria-label="Permalink to &quot;定义原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, const RegTrait&amp; regTrait = RegTraitNumOne&gt; struct RegTensor;</span></span></code></pre></div><h2 id="函数说明" tabindex="-1">函数说明 <a class="header-anchor" href="#函数说明" aria-label="Permalink to &quot;函数说明&quot;">​</a></h2><p>模板参数T，支持的数据类型(宽度)为b8/b16/b32/b64。</p><table tabindex="0"><thead><tr><th>数据类型宽度</th><th>数据类型</th></tr></thead><tbody><tr><td>b8</td><td>Ascend 950PR/Ascend 950DT，支持的数据类型为：bool/int8_t/uint8_t/fp4x2_e2m1_t/fp4x2_e1m2_t/hifloat8_t/fp8_e5m2_t/fp8_e4m3fn_t/fp8_e8m0_t（ fp4x2_e2m1_t/fp4x2_e1m2_t这两个b4类型在Vector侧的内存排布需要为两个一组，表现为b8类型；int4b_t也使用b8类型表达；bool数据类型只支持数据搬运）。</td></tr><tr><td>b16</td><td>Ascend 950PR/Ascend 950DT，支持的数据类型为：int16_t/uint16_t/half/bfloat16_t。</td></tr><tr><td>b32</td><td>Ascend 950PR/Ascend 950DT，支持的数据类型为：int32_t/uint32_t/float/complex32。</td></tr><tr><td>b64</td><td>Ascend 950PR/Ascend 950DT，支持的数据类型为：int64_t/uint64_t/complex64。</td></tr></tbody></table><p>模板参数regTrait，表示该RegTensor类型内部包含的矢量Reg数量。regTrait为RegTraitNumOne时，该RegTensor类型中包含1个相应数据类型的矢量Reg，长度为VL。regTrait为RegTraitNumTwo时，该RegTensor类型中包含2个相应数据类型的矢量Reg，总长度为2 * VL，每个矢量Reg长度为VL。</p><table tabindex="0"><thead><tr><th>模板参数regTrait</th><th>支持的数据类型宽度</th></tr></thead><tbody><tr><td>RegTraitNumOne</td><td>Ascend 950PR/Ascend 950DT，支持的数据类型宽度为：b8/b16/b32/b64。</td></tr><tr><td>RegTraitNumTwo</td><td>Ascend 950PR/Ascend 950DT，支持的数据类型宽度为：b64/complex32。</td></tr></tbody></table><h2 id="支持的型号" tabindex="-1">支持的型号 <a class="header-anchor" href="#支持的型号" aria-label="Permalink to &quot;支持的型号&quot;">​</a></h2><p>Ascend 950PR/Ascend 950DT（VL=256B）</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>示例一</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::Reg::RegTensor&lt;uint32_t&gt; reg;</span></span>
<span class="line"><span>AscendC::Reg::MaskReg mask = AscendC::Reg::CreateMask&lt;uint32_t&gt;();</span></span>
<span class="line"><span>AscendC::Reg::LoadAlign(reg, src, 0);</span></span>
<span class="line"><span>AscendC::Reg::Adds(reg, reg, 1);</span></span>
<span class="line"><span>AscendC::Reg::StoreAlign(dst, reg, 0, mask);</span></span></code></pre></div></li><li><p>示例二</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 针对B64,可以传入RegTraitNumTwo</span></span>
<span class="line"><span>template&lt;typename T, const AscendC::Reg::RegTrait&amp; Trait = AscendC::Reg::RegTraitNumOne&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void AddVF(__ubuf__ T* dstAddr, __ubuf__ T* src0Addr, __ubuf__ T* src1Addr, uint32_t count, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T,Trait&gt; srcReg0;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T,Trait&gt; srcReg1;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T,Trait&gt; dstReg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask;</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        mask = AscendC::Reg::UpdateMask&lt;T,Trait&gt;(count);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg0, src0Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg1, src1Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::Add(dstReg, srcReg0, srcReg1, mask);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dstAddr + i * oneRepeatSize, dstReg, mask);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul>`,16)])])}const h=a(i,[["render",l]]);export{R as __pageData,h as default};
